import math

def fake_embed(text: str) -> list[float]:
    # toy embedder: counts of a few keywords -> a 3-d vector
    keys = ["peanut", "metric", "python"]
    t = text.lower()
    return [float(t.count(k)) for k in keys]

class VectorMemory:
    def __init__(self):
        self.records = []  # list of {text, vector}

    def write(self, text: str):
        self.records.append({"text": text, "vector": fake_embed(text)})

    def read(self, query: str, k: int = 2) -> list[str]:
        q = fake_embed(query)
        def cos(v):
            dot = sum(a * b for a, b in zip(q, v))
            nq = math.sqrt(sum(a * a for a in q)) or 1e-9
            nv = math.sqrt(sum(b * b for b in v)) or 1e-9
            return dot / (nq * nv)
        ranked = sorted(self.records, key=lambda r: cos(r["vector"]), reverse=True)
        return [r["text"] for r in ranked[:k]]

