import math

def cosine(a: list[float], b: list[float]) -> float:
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0                      # avoid divide-by-zero on empty vectors
    return dot / (na * nb)

def retrieve(query_vec: list[float], memories: list[dict], k: int) -> list[str]:
    ranked = sorted(
        memories,
        key=lambda m: cosine(query_vec, m["vector"]),
        reverse=True,                   # most similar first
    )
    return [m["text"] for m in ranked[:k]]  # slice is safe when k > len

