import math

class VectorMemory:
    def __init__(self):
        self.records = []  # list of {"text": str, "vector": list[float]}

    def write(self, text: str, vector: list[float]) -> None:
        self.records.append({"text": text, "vector": vector})

    @staticmethod
    def _cosine(a: list[float], b: list[float]) -> float:
        dot = sum(x * y for x, y in zip(a, b))
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(y * y for y in b))
        if na == 0 or nb == 0:
            return 0.0  # empty/zero vector -> no similarity, no crash
        return dot / (na * nb)

    def search(self, query_vec: list[float], k: int = 3) -> list[str]:
        ranked = sorted(
            self.records,
            key=lambda r: self._cosine(query_vec, r["vector"]),
            reverse=True,
        )
        return [r["text"] for r in ranked[:k]]

if __name__ == "__main__":
    m = VectorMemory()
    m.write("allergic to peanuts", [1.0, 0.0])
    m.write("prefers metric", [0.0, 1.0])
    print(m.search([1.0, 0.1], k=1))
